head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/bns_common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/list_common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");
scwin.vScrenID = 'ULDBNS15500.gfm';
scwin.vMktactCd = '316'; //채권시장조치구분코드
scwin.vIsuCd = '', scwin.hasAttachDoc = '';
scwin.gBndApplId, scwin.gProcsStat = '';
scwin.vBndListProcsTpCd = 1; //채권처리구분(1:신청,2:접수)
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp; //접수 1, 반송 2, 처리완료 3, 수정 4, 표준코드요청 9
scwin.btnStat = new Object();
scwin.vViewYN = 'N';
scwin.vRowPos = 0;
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명  	 : fn_list_sync
 * 설명       : 목록조회
 ***********************************************/
scwin.fn_list_sync = function() {
    var dsNm = 'BNS_APPL_ACPT_LIST';
    var qryId = 'lds.stf.bnscommon.select.listApplAndAcpt';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    if (scwin.vBndListProcsTpCd == 1) {
        $c.cm.ShowWin(grd_List1);
    } else {
        $c.cm.ShowWin(grd_List2);
    }
};



/********************************************** 
 * 함수명   : fn_dtl_sync_Req
 * 설명       : 그리드 선택 시, 신청내역 상세내역을 조회한다.
 ***********************************************/
scwin.fn_dtl_sync_Req = function() {
    var dsNm = 'BNS_ISU_CHG_INFO';
    var qryId = 'lds.stf.bnsisuchg.select.readIsuChgInfoMiscDelist';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    param += '&{P}V_BND_APPL_ID=' + scwin.gBndApplId;
    param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsuInfo, dsNm, qryId, param);
};


/********************************************** 
 * 설명 : 채권신고담당자 조회
 ***********************************************/
scwin.fn_Search2 = function() {

	//----W-Craft WebSquare 변환 확인: ClearData----//
    dts_List3.ClearData();

	//----W-Craft WebSquare 변환 확인: NameString----//
    var isur_cd = dts_List.NameString(dts_List.RowPosition, "ISUR_CD");
    var dsNm = 'BNS_BND_DECL_CHRG_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectBndDeclChrgList';
    var param = '&{P}V_ISUR_CD=' + isur_cd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List3, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function(StrtDd) {
    if ($c.stf.getObjectValue(StrtDd) == '') {
        alert("[적용일]을 입력하십시오.");

	//----W-Craft WebSquare 변환 확인: focus----//
        edt_StrtDd.focus();
        return false;
    }
    if ($c.bns.fn_CheckDateObj(edt_StrtDd, "적용일")) {
        return false;
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_dtl_sync
 * 설명       : 그리드 선택 시 상세내역을 조회한다.
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.gBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    //종목정보
    var dsNm = 'BNS_ISU_INFO_BNS15500';
    var qryId = 'lds.stf.bnscommon.select.readIsuInfo.BNS15500';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsuInfo, dsNm, qryId, param);

    //기준금리상세(표면이자율,발행가액)
    dsNm = 'BNS_COUPNRT_ISURPRC';
    qryId = 'lds.stf.bnscommon.select.readCoupnRtAndIsurPrc';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CoupnRtAndIsurPrc, dsNm, qryId, param);

    //신용평가정보
    dsNm = 'BNS_CREDIT_INFO_BNS15500';
    qryId = 'lds.stf.bnscommon.select.listCredit.BNS15500';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Credit, dsNm, qryId, param);

    //인수기관정보
    dsNm = 'BNS_UDWRT_INST';
    qryId = 'lds.stf.bnscommon.select.listUdwrtInst';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_UdwrtInst, dsNm, qryId, param);

    //원리금정보
    dsNm = 'BNS_PRINCINT_INFO';
    qryId = 'lds.stf.bnscommon.select.listPrincint';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Princint, dsNm, qryId, param);

    //CALL
    dsNm = 'BNS_OPTION_CALL';
    qryId = 'lds.stf.bnscommon.select.listOptionCall';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_OptionCall, dsNm, qryId, param);

    //PUT
    dsNm = 'BNS_OPTION_PUT';
    qryId = 'lds.stf.bnscommon.select.listOptionPut';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_OptionPut, dsNm, qryId, param);

    //변동금리
    dsNm = 'BNS_CHG_INT';
    qryId = 'lds.stf.bnscommon.select.listChgInt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ChgInt, dsNm, qryId, param);

    //분할상환
    dsNm = 'BNS_SPLIT_REDMPT';
    qryId = 'lds.stf.bnscommon.select.listSplitRedmpt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SplitRedmpt, dsNm, qryId, param);

    //유동화자산
    dsNm = 'BNS_SECUTIZ_ASST';
    qryId = 'lds.stf.bnscommon.select.listSecutizAsst';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SecutizAsst, dsNm, qryId, param);

    //주식관련 행사가격 조정 JACKAL_190220
    dsNm = 'BNS_STOCK_REL_EXECPRC_ADJ';
    qryId = 'lds.stf.bnscommon.select.listStockRelExerPrcAdj';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_StockRel, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SplitRedmptDdAutoCreate
 * 설명       : 분할상환일 자동생성.
 * JACKAL_190220
 ***********************************************/
scwin.fn_SplitRedmptDdAutoCreate = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.gBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var vFstSplitRedmptDd = $c.stf.getObjectValue(edt_FstSplitRedmptDd);
    var vSplitRedmptCycle = $c.stf.getObjectValue(edt_SplitRedmptCycle);
    var vSplitRedmptMmendTpCd = $c.stf.getObjectValue(cmb_SplitRedmptMmendTpCd);
    var vEquivRedmptVal = $c.stf.getObjectValue(edt_EquivRedmptVal);
    var vSplitRedmptCnt = $c.stf.getObjectValue(edt_SplitRedmptCnt);
    param += "&{P}V_FST_SPLIT_REDMPT_DD=" + vFstSplitRedmptDd; //최초분할상환일자
    param += "&{P}V_SPLIT_REDMPT_CYCLE=" + vSplitRedmptCycle; //분할상환주기
    param += "&{P}V_SPLIT_REDMPT_MMEND_TP_CD=" + vSplitRedmptMmendTpCd; //분할상환월말구분코드
    param += "&{P}V_EQUIV_REDMPT_VAL=" + vEquivRedmptVal; //균등상환액
    param += "&{P}V_SPLIT_REDMPT_CNT=" + vSplitRedmptCnt; //분할상환횟수

    //분할상환
    dsNm = 'BNS_SPLIT_REDMPT';
    qryId = 'lds.stf.bnscommon.select.listSplitRedmptAutoCreate';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SplitRedmpt, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_StockRelAutoInput
 * 설명       : 주식관련 행사가격 조정 자동생성.
 * JACKAL_190220
 ***********************************************/
scwin.fn_StockRelAutoInput = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.gBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var vFstExerPrcAdjDd = $c.stf.getObjectValue(edt_FstExerPrcAdjDd);
    var vExerPrcAdjCycle = $c.stf.getObjectValue(edt_ExerPrcAdjCycle);
    var vStkcertMmendTpCd = $c.stf.getObjectValue(cmb_StkcertMmendTpCd);
    var vExerPrcAdjCnt = $c.stf.getObjectValue(edt_ExerPrcAdjCnt);
    param += "&{P}V_FST_EXER_PRC_ADJ_DD=" + vFstExerPrcAdjDd; //최초분할상환일자
    param += "&{P}V_EXER_PRC_ADJ_CYCLE=" + vExerPrcAdjCycle; //분할상환주기
    param += "&{P}V_STKCERT_MMEND_TP_CD=" + vStkcertMmendTpCd; //분할상환월말구분코드
    param += "&{P}V_EXER_PRC_ADJ_CNT=" + vExerPrcAdjCnt; //분할상환횟수

    //분할상환
    dsNm = 'BNS_STOCK_REL_EXECPRC_ADJ';
    qryId = 'lds.stf.bnscommon.select.listStockRelExerPrcAdjAutoInput';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_StockRel, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_ChgIntRtAutoInput
 * 설명       : 변동금리 금리결정기준일 자동생성.
 * JACKAL_190509
 ***********************************************/
scwin.fn_ChgIntRtAutoInput = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.gBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var vIsuDd = $c.stf.getObjectValue(edt_IsuDd);
    var vFstIntPayDd = $c.stf.getObjectValue(edt_FstIntPayDd);
    var vIntPayUnitMms = $c.stf.getObjectValue(edt_IntPayUnitMms);
    var vIntMmendTpCd = $c.stf.getObjectValue(cmb_IntMmendTpCd);
    var vIntPayCnt = $c.stf.getObjectValue(edt_IntPayCnt);
    var vIntDecsnBasDys = $c.stf.getObjectValue(edt_IntDecsnBasDys);
    param += "&{P}V_ISU_DD=" + vIsuDd; //발행일
    param += "&{P}V_FST_INT_PAY_DD=" + vFstIntPayDd; //최초이자지급일
    param += "&{P}V_INT_PAY_UNIT_MMS=" + vIntPayUnitMms; //이자지급주기
    param += "&{P}V_INT_MMEND_TP_CD=" + vIntMmendTpCd; //이자월말구분코드
    param += "&{P}V_INT_PAY_CNT=" + vIntPayCnt; //이자분할상환횟수
    param += "&{P}V_INT_DECSN_BAS_DYS=" + vIntDecsnBasDys; //금리결정기준일수

    //변동금리 
    dsNm = 'BNS_CHG_INT';
    qryId = 'lds.stf.bnscommon.select.listChgInt.Jikjun.AutoInput';
    vIntDecsnBasTpCd = $c.stf.getObjectValue(cmb_IntDecsnBasTpCd);
    if (vIntDecsnBasTpCd == '2') //  금일결정기준일 구분이 당해 이자지급일이면
        qryId = 'lds.stf.bnscommon.select.listChgInt.DangHae.AutoInput';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ChgInt, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_CallOptionAutoCreate
 * 설명       : CALL_OPTION 행사일 자동생성.
 * JACKAL_190726
 ***********************************************/
scwin.fn_CallOptionAutoCreate = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.gBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var vFstCallExerDd = $c.stf.getObjectValue(edt_FstCallExerDd);
    var vCallExerCycle = $c.stf.getObjectValue(edt_CallExerCycle);
    var vCallMmendTpCd = $c.stf.getObjectValue(cmb_CallMmendTpCd);
    var vCallExerCnt = $c.stf.getObjectValue(edt_CallExerCnt);
    param += "&{P}V_FST_CALL_EXER_DD=" + vFstCallExerDd; //최초분할상환일자
    param += "&{P}V_CALL_EXER_CYCLE=" + vCallExerCycle; //분할상환주기
    param += "&{P}V_CALL_MMEND_TP_CD=" + vCallMmendTpCd; //분할상환월말구분코드
    param += "&{P}V_CALL_EXER_CNT=" + vCallExerCnt; //분할상환횟수

    //옵션행사
    dsNm = 'BNS_OPTION_CALL';
    qryId = 'lds.stf.bnscommon.select.listCallOption.AutoCreate';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_OptionCall, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_PutOptionAutoCreate
 * 설명       : PUt_OPTION 행사일 자동생성.
 * JACKAL_190726
 ***********************************************/
scwin.fn_PutOptionAutoCreate = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.gBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    var vFstPutExerDd = $c.stf.getObjectValue(edt_FstPutExerDd);
    var vPutExerCycle = $c.stf.getObjectValue(edt_PutExerCycle);
    var vPutMmendTpCd = $c.stf.getObjectValue(cmb_PutMmendTpCd);
    var vPutExerCnt = $c.stf.getObjectValue(edt_PutExerCnt);
    param += "&{P}V_FST_PUT_EXER_DD=" + vFstPutExerDd; //최초분할상환일자
    param += "&{P}V_PUT_EXER_CYCLE=" + vPutExerCycle; //분할상환주기
    param += "&{P}V_PUT_MMEND_TP_CD=" + vPutMmendTpCd; //분할상환월말구분코드
    param += "&{P}V_PUT_EXER_CNT=" + vPutExerCnt; //분할상환횟수

    //옵션행사
    dsNm = 'BNS_OPTION_PUT';
    qryId = 'lds.stf.bnscommon.select.listPutOption.AutoCreate';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_OptionPut, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터를 정의한다.
 ***********************************************/
scwin.fn_SetComboCode = function() {
    //기관코드
    var qryId = 'lds.stf.bnscommon.select.listInstCd';
    var dsNm = 'BNS_INST_INFO';
    var param = '&{P}V_INST_NM=';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_InstCd, dsNm, qryId, param);
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_AsstHdTpCd, '03374'); //자산보유자 유형
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_SecutizAsstTpCd, '03375'); //유동화자산 유형
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_CoupntRtCd, '03050'); //표면이자율결정 기준금리

    //공통콤보
    var arrCid = [];
    arrCid.push({
        cid: '02475',
        cnm: 'cmb_CurrTpCd'
    }); //발행통화				
    arrCid.push({
        cid: '01422',
        cnm: 'cmb_BndTpCd'
    }); //채권유형				
    arrCid.push({
        cid: '03076',
        cnm: 'cmb_MunibndTpCd'
    }); //지방채구분				
    arrCid.push({
        cid: '03221',
        cnm: 'cmb_NusualBndTpCd'
    }); //특이채권유형			
    arrCid.push({
        cid: '03055',
        cnm: 'cmb_BndGuarTpCd'
    }); //보증/담보				
    arrCid.push({
        cid: '00872',
        cnm: 'cmb_IntPayMethdCd'
    }); //이자지급방법			
    arrCid.push({
        cid: '03075',
        cnm: 'cmb_AsstSecutizTpCd'
    }); //유동화					
    arrCid.push({
        cid: '03054',
        cnm: 'cmb_ImbdoptCorpbndCd'
    }); //옵션					
    arrCid.push({
        cid: '03563',
        cnm: 'cmb_CondCapSecuTpCd'
    }); //조건부자본증권유형		
    arrCid.push({
        cid: '03053',
        cnm: 'cmb_DebtRepayRankTpCd'
    }); //선/후/중순위			
    arrCid.push({
        cid: '03096',
        cnm: 'cmb_BkHoldyPrincPayDdDecsnCd'
    }); //휴무관련(원금)			
    arrCid.push({
        cid: '03096',
        cnm: 'cmb_BkHoldyDdIntPayMethdCd'
    }); //휴무관련(이자)			
    arrCid.push({
        cid: '01513',
        cnm: 'cmb_CoupnPayMethdCd'
    }); //이자 선/후급			
    arrCid.push({
        cid: '03195',
        cnm: 'cmb_BndIntPayDdBasTpCd'
    }); //이자일지급구분			
    arrCid.push({
        cid: '03512',
        cnm: 'cmb_IntUdwonProcsCd'
    }); //이자원단위 미만처리		
