    if (scwin.fn_chkPut() > 0) return 1;

    //분할상환체크
    rowCnt = dts_SplitRedmpt.CountRow;
    for (var idx = 1; idx <= rowCnt; idx++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        if (dts_SplitRedmpt.NameValue(idx, 'INT_PAY_DD').length != 8) {
            alert('분할상환탭 불균등 정보를 확인하여 주십시요.');
            dts_SplitRedmpt.RowPosition = idx;
            return 1;
        }
    }

    //원리금정보
    rowCnt = dts_Princint.CountRow;
    for (var idx = 1; idx <= rowCnt; idx++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        if (dts_Princint.NameValue(idx, 'INT_PAY_DD').length != 8) {
            alert('원리금탭 정보를 확인하여 주십시요.');
            dts_Princint.RowPosition = idx;
            return 1;
        }
    }

    // 분리형BW여부가 체크가 안된 경우만 메세지 확인함. jackal_181210 190426 추가
    if (!chk_DetachBwYn.checked) {
        if ($c.stf.getObjectValue(cmb_StkRelCorpbndRghtTpCd) != '' &&
            $c.stf.getObjectValue(cmb_NusualBndTpCd) != '2') {
            msg = "" + "특이채권유형이 " + $c.stf.fn_getComboTextValue(cmb_NusualBndTpCd) + " 인데 " + "\n주식관련탭의 권리구분이 [" + $c.stf.fn_getComboTextValue(cmb_StkRelCorpbndRghtTpCd) + "]로 입력되어 있습니다." + "\n" + "\n주식관련탭의 권리구분은 주식관련사채일때만 입력가능한 항목입니다." + "\n그래도 작업을 계속하시겠습니까?";
            if (!window.confirm(msg)) return 1;
        }
    }

    //ELB등 
    if ($c.stf.getObjectValue(cmb_NusualBndTpCd) == '3' ||
        $c.stf.getObjectValue(cmb_NusualBndTpCd) == '4') {
        if ($c.stf.getObjectValue(edt_PrincGrtRt) == '') {
            alert("원금보장율을 입력하십시오.");
            return 1;
        }
    } else if ($c.stf.getObjectValue(edt_PrincGrtRt) == '') {
        if ($c.stf.getObjectValue(cmb_NusualBndTpCd) == '3' ||
            $c.stf.getObjectValue(cmb_NusualBndTpCd) == '4') {
            alert("ELB등 탭은 ELS/DLS채권시에만 입력합니다. 특이채권유형을 확인바랍니다.");
            return 1;
        }
    }

	//----W-Craft WebSquare 변환 확인: NameValue----//
    if (dts_IsuInfo.NameValue(1, "INT_PAY_METHD_CD") == '' ||

	//----W-Craft WebSquare 변환 확인: NameValue----//
        dts_IsuInfo.NameValue(1, "INT_PAY_METHD_CD").substring(0, 1) == '1') {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        if (dts_IsuInfo.NameValue(1, "INT_RT_DECSN_MISC_BAS_INT_NM") != '') {
            alert("변동금리탭은 변동금리시에만 입력합니다. 이자지급방법을 확인바랍니다.");
            return 1;
        }
    }

	//----W-Craft WebSquare 변환 확인: NameValue----//
    if (dts_IsuInfo.NameValue(1, "IMBDOPT_CORPBND_CD") == '' &&
        (dts_OptionCall.CountRow > 0 || dts_OptionPut.CountRow > 0)) {
        alert("CALL/PUT 탭은 옵션일 경우에만 입력합니다. 옵션구분을 확인바랍니다.");
        return 1;
    }

	//----W-Craft WebSquare 변환 확인: NameValue----//
    if (dts_IsuInfo.NameValue(1, "ASST_SECUTIZ_TP_CD") == '' &&

	//----W-Craft WebSquare 변환 확인: NameValue----//
        dts_IsuInfo.NameValue(1, "SECUTIZ_ADM_INST_CD").substring(0, 1) == '1') {
        alert("유동화탭은 유동화 채권일 경우에만 입력합니다. 유동화채권 인지 확인바랍니다.");
        return 1;
    }
    if (!$c.stf.checkMaxLength(txb_IntRtDecsnMiscBasIntNm, 20, '기타기준금리')) return 1;
    if (!$c.stf.checkMaxLength(txb_NusualIsuCondContn, 60, '특이발행조건(외부용)')) return 1;
    if (!$c.stf.checkMaxLength(txb_MemoContn, 200, '기타참고사항(내부용)')) return 1;
    if (!$c.stf.checkMaxLength(txb_UlyContn, 100, '기초자산상세내용')) return 1;
    if (!$c.stf.checkMaxLength(txb_ElsCondContn1, 100, '조건내용1')) return 1;
    if (!$c.stf.checkMaxLength(txb_ElsCondContn2, 100, '조건내용2')) return 1;

    // jackal_16.10.11  call put 사유 길이 체크 추가
    if (!$c.stf.checkMaxLength(txb_CallExerRsn, 50, '콜 사유')) return 1;
    if (!$c.stf.checkMaxLength(txb_PutExerRsn, 50, '풋 사유')) return 1;

    //환율적용 발행금액,상장금액 체크
    if ($c.stf.getObjectValue(cmb_CurrTpCd) != '' &&
        $c.stf.getObjectValue(cmb_CurrTpCd) != '1') {
        var isuAmt = $c.stf.getObjectValue(edt_IsuAmt);
        var listAmt = $c.stf.getObjectValue(edt_ListAmt);
        if (isuAmt == '') isuAmt = 0;
        if (listAmt == '') listAmt = 0;
        var exchrt = $c.bns.fn_SearchExchrt(scwin.vScrenID, dts_CheckExa, $c.stf.getObjectValue(cmb_CurrTpCd), '1');
        isuAmt = isuAmt * exchrt;
        listAmt = listAmt * exchrt;

        //메시지 추가 발행금액이 상장금액보다 크거나 같아야 합니다.
        if (parseInt(isuAmt) < parseInt(listAmt)) {
            alert("발행금액은 상장금액보다 크거나 같아야 합니다.");
            return 1;
        }
        if (isuAmt <= 100000000) {
            alert("발행금액이 1억원 이하입니다.");
        } else if (isuAmt >= 1000000000000) {
            alert("발행금액이 1조원 이상입니다.");
        }
        if (listAmt <= 100000000) {
            alert("상장금액이 1억원 이하입니다.");
        } else if (listAmt >= 1000000000000) {
            alert("상장금액이 1조원 이상입니다.");
        }
    }

    // 분리형BW여부가 체크는 특이채권유형이 일반채권인 경우만 체크가능 jackal_181210 190426 추가
    if (chk_DetachBwYn.checked) {
        if ($c.stf.getObjectValue(cmb_NusualBndTpCd) != '1') {
            msg = "" + "분리형BW가 체크된 경우 특이채권유형이 [1 일반채권] 이어야 합니다." + "\n특이채권유형이 [" + $c.stf.fn_getComboTextValue(cmb_NusualBndTpCd) + "]로 입력되어 있습니다.";
            alert(msg);
            return 1;
        }
    }


    //  분리형BW여부가 체크되어 있스면 권리구분이 21 이어야 하고 jackal_181210 190426 추가
    if (chk_DetachBwYn.checked) {
        // 주식관련 권리구분 21 setting
        if ($c.stf.getObjectValue(cmb_StkRelCorpbndRghtTpCd) != '21') {
            msg = "" + "분리형BW가 체크된 경우 주식관련탭의 권리구분이 [21 신주인수권(분리형)] 이어야 합니다. " + "\n주식관련탭의 권리구분이 [" + $c.stf.fn_getComboTextValue(cmb_StkRelCorpbndRghtTpCd) + "]로 입력되어 있습니다.";
            alert(msg);
            return 1;
        }
    }

    // 더불어 특이채권유형이 2(주권관련채권) 이면 21은 선택 못하게 해야 함. jackal_181210 190426 추가
    if ($c.stf.getObjectValue(cmb_NusualBndTpCd) == '2') {
        if ($c.stf.getObjectValue(cmb_StkRelCorpbndRghtTpCd) == '21') {
            msg = "" + "특이채권유형이 " + $c.stf.fn_getComboTextValue(cmb_NusualBndTpCd) + " 인데 " + "\n주식관련탭의 권리구분이 [" + $c.stf.fn_getComboTextValue(cmb_StkRelCorpbndRghtTpCd) + "]로 입력되어 있습니다." + "\n" + "\n이 권리구분은 일반채권 분리형BW가 체크 되었을때만 입력가능한 항목입니다.";
            alert(msg);
            return 1;
        }
    }

    //이자지급방법이 변동금리형이면
    if ($c.stf.getObjectValue(cmb_IntPayMethdCd) > 20) {
        // 금리결정기준일 1~10 일까지 만 입력 체크   JACKAL_190509
        var vIntDecsnBasDys = $c.stf.getObjectValue(edt_IntDecsnBasDys);
        if (vIntDecsnBasDys != '' && (vIntDecsnBasDys > 10 || vIntDecsnBasDys < 1)) {
            if (!window.confirm('변동금리 탭의 이자지급기준일로부터 금리결정기준일은 1 ~ 10 일전 까지만 선택가능합니다.\n그래도 처리하시겠습니까?')) return 1;
        }
    }
    return 0;
};


/********************************************** 
 * 함수명   : fn_AcptProcsCheck
 * 설명      : 접수, 처리완료시 공통 체크 구문
 ***********************************************/
scwin.fn_AcptProcsCheck = function(gubun) {
    if (gubun == 'Acpt') {
        //필수입력값 체크
        if (scwin.fn_InputCheck(edt_StrtDd) == false) return 1;

        //적용일,매매일,마감일,채권마감 체크		
        //if (fn_CheckCmData(vScrenID, dts_CheckCmData, getObjectValue(edt_StrtDd), gBndApplId) > 0) return 1;

        if ($c.bns.fn_CheckCmData2(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd), scwin.gBndApplId) > 0) return 1;

	//----W-Craft WebSquare 변환 확인: NameValue----//
        scwin.vIsuCd = dts_IsuInfo.NameValue(1, "ISU_CD");
    } else if (gubun == 'Procs') {
        //필수입력값 체크
        if (scwin.fn_InputCheck(edt_StrtDd2) == false) return 1;

        //적용일,매매일,마감일,채권마감 체크		
        //if (fn_CheckCmData(vScrenID, dts_CheckCmData, getObjectValue(edt_StrtDd2), gBndApplId) > 0) return 1;
        if ($c.bns.fn_CheckCmData2(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd), scwin.gBndApplId) > 0) return 1;

	//----W-Craft WebSquare 변환 확인: NameValue----//
        scwin.vIsuCd = dts_IsuInfo.NameValue(1, "STD_CD");
    }

	//----W-Craft WebSquare 변환 확인: NameValue----//
    scwin.hasAttachDoc = dts_IsuInfo.NameValue(1, "HAS_ATTACH_DOC");
    return 0;
};


/*************************************************************
 * 함수명	: fn_CheckSplitRedmptIsuCd
 * 설명		: 분할상환 전송대상 종목인지 체크
 * param		: vScrenID, vIsuCd, vCurDd
 *************************************************************/
scwin.fn_CheckSplitRedmptIsuCd = function(vScrenID, dtsObj, vIsuCd, vCurDd) {
    var dsNm = 'BNS_MULTACT_IMPSBLE_RULE';
    var qryId = 'lds.stf.bnscommon.select.readSplitRedmptIsuCdCheck316';
    var param = '';
    param += '&{P}V_STD_CD=' + scwin.vIsuCd;
    param += '&{P}V_CLS_DD=' + vCurDd;

    //alert(vIsuCd);
    //alert(vCurDd);

    dtsObj.SyncLoad = "true";
    $c.bns.fn_SearchBns(scwin.vScrenID, dtsObj, dsNm, qryId, param);
    var output = '분할상환 전송대상 종목입니다.';
    output += '\n' + '상장마감 분할상환정보 조치내역을 확인하여 주십시오.';

	//----W-Craft WebSquare 변환 확인: NameValue----//
    if (dtsObj.NameValue(1, 'MULTACT_IMPSBL_CNT') > 0) {
        alert(output);
        return 1;
    }
    return 0;
};



/********************************************** 
 * 함수명   : fn_Acpt
 * 설명       : 신청데이터를 접수 처리한다.
 ***********************************************/
scwin.fn_Acpt = function() {
    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck('Acpt') > 0) return;

    //복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRule(scwin.vScrenID, dts_Temp, scwin.vIsuCd, scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd)) > 0) return;

    //분할상환 전송대상 종목인지 체크
    if (scwin.fn_CheckSplitRedmptIsuCd(scwin.vScrenID, dts_Temp, scwin.vIsuCd, $c.ut.cGetToday("yyyymmdd")) > 0) return;

    //첨부문서 체크
    if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '접수')) return;

    //변경된 데이터가 없더라도 데이터셋 전송
    dts_IsuInfo.UseChangeInfo = "False";
    var url = "/bns/IsuChgEtc.do?method=processApplAcpt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    url += "&REG_YN=" + 'N';
    trs_Save.Action = $c.lce.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_IsuInfo)";

	//----W-Craft WebSquare 변환 확인: Post----//
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 처리완료 및 수정을 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck('Procs') > 0) return;

    //종목정보체크
    if ($c.bns.fn_CheckNewListIsuInfo(dts_IsuInfo) > 0) return;
    if (scwin.fn_CheckEach() > 0) return;
    if (scwin.processGp == '4') {
        if ($c.bns.fn_CheckModAndRet(scwin.vScrenID, dts_CheckCmData, scwin.gBndApplId) > 0) return;
    }
    //채권분류코드와 발행기관, 채권유형 등과 맞는지 체크한다.
    if ($c.bns.fn_ChkBndClssAndIsur(scwin.vScrenID, dts_IsuInfo, scwin.vMktactCd) > 0) return;

    //고객요건에의한 체크 추가. 2024-06-05 by김효준 
    if ($c.bns.fn_AddCheck() > 0) return;

    //복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRuleProcEnd(scwin.vScrenID, dts_Temp, scwin.vIsuCd, scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd2)) > 0) return;

    // 중복시장조치코드에따른 alert(일별금액조정과 중복가능)   2024.08.23 by no3.

	//----W-Craft WebSquare 변환 확인: NameString----//
    if (dts_IsuInfo.NameString(1, "DUP_MKTACT_CD") == "320") {
        alert("일괄상장 일별금액조정 화면과 중복조치가 발생했습니다.\n\"발행금액\"과 \"상장금액\"을 확인하시기 바랍니다.");
    }

    //발행방법설정

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameValue----//
    var ISU_METHD_INDIRECT = dts_IsuInfo.NameValue(1, 'ISU_METHD_INDIRECT');

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var ISU_METHD_DIRECT = dts_IsuInfo.NameValue(1, 'ISU_METHD_DIRECT');

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var ISU_METHD_PPBOND = dts_IsuInfo.NameValue(1, 'ISU_METHD_PPBOND'); /*ORG SRC: dts_IsuInfo.NameValue(1, 'BND_ISU_METHD_CD') = ISU_METHD_INDIRECT + '' + ISU_METHD_DIRECT + '' + ISU_METHD_PPBOND*/ X = ISU_METHD_INDIRECT + '' + ISU_METHD_DIRECT + '' + ISU_METHD_PPBOND;

    //탭 데이터셋 설정
    scwin.fn_SetCreditData();
    scwin.fn_SetUdwrtInstData();
    scwin.fn_SetSecutizAsstData();
    scwin.fn_SetBasIntRtData();

    //변경된 데이터가 없더라도 데이터셋 전송하여 처리완료 진행
    dts_IsuInfo.UseChangeInfo = "False";
    dts_OptionCall.UseChangeInfo = "False";
    dts_OptionPut.UseChangeInfo = "False";
    dts_Princint.UseChangeInfo = "False";
    dts_SplitRedmpt.UseChangeInfo = "False";
    dts_ChgInt.UseChangeInfo = "False";
    // 주식관련 행사가격 조정 JACKAL_190220
    dts_StockRel.UseChangeInfo = "False";
    var url;
    if (scwin.processGp == '4') {
        //접수 후 수정 및 반송시 체크한다.			
        if ($c.bns.fn_CheckModAndRet(scwin.vScrenID, dts_CheckCmData, scwin.gBndApplId) > 0) return;
        if (!confirm("수정처리 하시겠습니까?")) return;
        url = "/bns/IsuChgEtc.do?method=updateAcpt";
    } else {
        if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '처리완료')) return;
        url = "/bns/IsuChgEtc.do?method=processAcptProcessComplt";
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    var param = "BND_APPL_ID=" + scwin.gBndApplId;
    param += ", BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;

	//----W-Craft WebSquare 변환 확인: NameValue----//
    param += ", STRT_DD=" + dts_IsuInfo.NameValue(1, "STRT_DD");

	//----W-Craft WebSquare 변환 확인: NameValue----//
    param += ", STD_CD=" + dts_IsuInfo.NameValue(1, "STD_CD");
    // jackal_140515 변동금리 표면이자율결정금리 변경가능토록 수정

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameValue----//
    /*ORG SRC: dts_IsuInfo.NameValue(1, 'COUPN_RT_DECSN_BAS_INT_CD') = getObjectValue(cmb_CoupnRtDecsnBasIntCd);*/
    X = $c.stf.getObjectValue(cmb_CoupnRtDecsnBasIntCd);

    // 분리형BW여부 설정 jackal_181210 190426 추가

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameValue----//
