/********************************************** 
 * 함수명   : fn_SetUdwrtInst
 * 설명       : 인수기관 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetUdwrtInst = function(rowIdx, cbObj, edtObj) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var UDWRT_INST_CD = dts_UdwrtInst.NameValue(rowIdx, 'UDWRT_INST_CD');
    if (UDWRT_INST_CD == '9999') {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        $c.stf.setObjectValue(edt_UdwrtAmt5, dts_UdwrtInst.NameValue(rowIdx, 'UDWRT_AMT'));
    } else {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        $c.stf.setObjectValue(cbObj, dts_UdwrtInst.NameValue(rowIdx, 'UDWRT_INST_CD'));

	//----W-Craft WebSquare 변환 확인: NameValue----//
        $c.stf.setObjectValue(edtObj, dts_UdwrtInst.NameValue(rowIdx, 'UDWRT_AMT'));
    }
};



