/********************************************** 
 * 함수명   : fn_SetSecutizAsstHdTpCd
 * 설명       : 자산보유자 설정한다.
 ***********************************************/
scwin.fn_SetSecutizAsstHdTpCd = function(rowIdx, cbHdTpObj, cbHdInstObj, cbAdmObj) {
    //자산보유자유형

	//----W-Craft WebSquare 변환 확인: NameValue----//
    $c.stf.setObjectValue(cbHdTpObj, dts_SecutizAsst.NameValue(rowIdx, 'ASST_HD_TP_CD'));

	//----W-Craft WebSquare 변환 확인: NameValue----//
    $c.stf.setObjectValue(txb_AsstHdTpMiscContn, dts_SecutizAsst.NameValue(rowIdx, 'ASST_HD_TP_MISC_CONTN'));

    //자산보유자기관
    var cbdata = '';

	//----W-Craft WebSquare 변환 확인: NameValue----//
    cbdata = "^ ," + dts_SecutizAsst.NameValue(rowIdx, 'ASST_HD_INST_CD') + "^" + dts_SecutizAsst.NameValue(rowIdx, 'ASST_HD_INST_NM');
    cbHdInstObj.CBData = cbdata;

