    //팀장확인데이터셋설정

	//----W-Craft WebSquare 변환 확인: SetDataHeader----//
    dts_Temp.SetDataHeader("TEMP:String");

	//----W-Craft WebSquare 변환 확인: AddRow----//
    dts_Temp.AddRow();
};
