scwin.dts_List_OnLoadError = function() {
    alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (scwin.vBndListProcsTpCd == 2) {
        $c.cm.CloseWin(rowcount, grd_List2);
        //접수,수정,처리완료,팀장확인 시 해당 ROW로 이동
        $c.bns.fn_RowPos(dts_List, scwin.vRowPos);

        // 중복조치건은 그리드 색깔 변경. 2024.08.23
        // 일별금액조정-기타변경, 일별금액조정-월별금액조정  중복조치가 가능
        scwin.fn_ChangeGridBgColor();
    } else {
        $c.cm.CloseWin(rowcount, grd_List1);
    }
};
scwin.dts_List_OnRowPosChanged = function(row) {
    if (row > 0) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        scwin.gBndApplId = dts_List.NameValue(row, "BND_APPL_ID");
        if (scwin.vBndListProcsTpCd == 2) {
            scwin.fn_dtl_sync();
        } else {
            // 채권신고담당자 조회
            scwin.fn_Search2();
            scwin.fn_dtl_sync_Req();
        }

	//----W-Craft WebSquare 변환 확인: NameValue----//
        scwin.gProcsStat = dts_List.NameValue(row, "PROCS_STAT");
        scwin.fn_ProcBtnStat();
    } else {

	//----W-Craft WebSquare 변환 확인: ClearData----//
        dts_IsuInfo.ClearData();

	//----W-Craft WebSquare 변환 확인: ClearData----//
        dts_List3.ClearData();
        scwin.vRowCount = 0;
    }
};
